package multipartbody

import (
	"io"
	"mime"
	"mime/multipart"
	"strings"
	"testing"
)

func TestNewFileWithFields(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFileWithFields("file", "doc.pdf", strings.NewReader("contents"), []TextField{
		{Name: "deal_id", Value: "42"},
		{Name: "person_id", Value: "7"},
	})
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	_, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type %q: %v", contentType, err)
	}

	reader := multipart.NewReader(body, params["boundary"])
	fields := map[string]string{}
	var fileName, fileBody string
	for {
		part, err := reader.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		data, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		if part.FileName() != "" {
			fileName = part.FileName()
			fileBody = string(data)
			continue
		}
		fields[part.FormName()] = string(data)
	}

	if fileName != "doc.pdf" || fileBody != "contents" {
		t.Fatalf("unexpected file part: name=%q body=%q", fileName, fileBody)
	}
	if fields["deal_id"] != "42" || fields["person_id"] != "7" {
		t.Fatalf("unexpected fields: %#v", fields)
	}
}

func TestNewFileValidation(t *testing.T) {
	t.Parallel()

	if _, _, err := NewFile("", "doc.pdf", strings.NewReader("x")); err == nil {
		t.Fatal("expected error for empty field name")
	}
	if _, _, err := NewFile("file", "", strings.NewReader("x")); err == nil {
		t.Fatal("expected error for empty file name")
	}
	if _, _, err := NewFile("file", "doc.pdf", nil); err == nil {
		t.Fatal("expected error for nil source")
	}
	if _, _, err := NewFileWithFields("file", "doc.pdf", strings.NewReader("x"), []TextField{{Name: "", Value: "v"}}); err == nil {
		t.Fatal("expected error for empty text field name")
	}
}

